package org.sigf.services;
import org.sigf.app.*; import org.sigf.config.*; import org.sigf.security.*; import org.sigf.services.*; import org.sigf.ui.*; import org.sigf.domain.*;

import java.sql.*; import java.util.*; import java.math.*;
/** Durable purchase intent, with safe retry after a lost connection. */
public final class PurchaseRecovery {
 private final Database db; private final Operations operations;
 public record Pending(UUID id,Long supplier,List<PurchaseItem> items){}
 public PurchaseRecovery(Database db){this.db=db;operations=new Operations(db);}
 public void save(Security.User user,Pending request)throws SQLException {user.admin();if(request.id()==null||request.items().isEmpty())throw new IllegalArgumentException("Compra vacía");List<PurchaseItem> normalized=new ArrayList<>();Set<String> seen=new HashSet<>();for(var i:request.items()){if(i.productId()<=0||i.lot()==null||i.lot().isBlank()||i.expiry()==null||i.quantity()<=0||i.cost()==null||i.cost().signum()<0)throw new IllegalArgumentException("Línea de compra inválida");String lot=i.lot().trim();if(!seen.add(i.productId()+"/"+lot))throw new IllegalArgumentException("No repita producto y lote");normalized.add(new PurchaseItem(i.productId(),lot,i.expiry(),i.quantity(),i.cost().setScale(2,RoundingMode.UNNECESSARY)));}try(Connection c=db.connection()){c.setAutoCommit(false);try{Security.verify(c,user,true);try(PreparedStatement lock=c.prepareStatement("select pg_advisory_xact_lock(hashtextextended(?,0))")){lock.setString(1,"sigf_purchase_pending:"+user.id());lock.execute();}try(PreparedStatement q=c.prepareStatement("select actor_id,supplier_id,acknowledged_at,cancelled from purchase_request where request_id=?")){q.setObject(1,request.id());try(ResultSet r=q.executeQuery()){if(r.next()){Long supplier=(Long)r.getObject(2);if(r.getLong(1)!=user.id()||!Objects.equals(supplier,request.supplier())||r.getBoolean(4)||!sameLines(c,request.id(),normalized))throw new IllegalArgumentException("La solicitud no coincide o ya fue cerrada");c.commit();return;}}}try(PreparedStatement q=c.prepareStatement("select 1 from purchase_request where actor_id=? and acknowledged_at is null")){q.setLong(1,user.id());try(ResultSet r=q.executeQuery()){if(r.next())throw new IllegalArgumentException("Tiene una compra pendiente; resuélvala antes de registrar otra");}}try(PreparedStatement s=c.prepareStatement("insert into purchase_request(request_id,actor_id,supplier_id) values(?,?,?)")){s.setObject(1,request.id());s.setLong(2,user.id());if(request.supplier()==null)s.setNull(3,Types.BIGINT);else s.setLong(3,request.supplier());s.executeUpdate();}try(PreparedStatement s=c.prepareStatement("insert into purchase_request_line(request_id,line_no,product_id,lot,expires_on,quantity,unit_cost) values(?,?,?,?,?,?,?)")){int index=0;for(var i:normalized){s.setObject(1,request.id());s.setInt(2,index++);s.setLong(3,i.productId());s.setString(4,i.lot());s.setDate(5,java.sql.Date.valueOf(i.expiry()));s.setInt(6,i.quantity());s.setBigDecimal(7,i.cost());s.addBatch();}s.executeBatch();}c.commit();}catch(Exception e){c.rollback();throw e;}}}
 private static boolean sameLines(Connection c,UUID id,List<PurchaseItem> input)throws SQLException {List<PurchaseItem> stored=lines(c,id);if(stored.size()!=input.size())return false;for(int i=0;i<stored.size();i++){var a=stored.get(i);var b=input.get(i);if(a.productId()!=b.productId()||!a.lot().equals(b.lot())||!a.expiry().equals(b.expiry())||a.quantity()!=b.quantity()||a.cost().compareTo(b.cost())!=0)return false;}return true;}
 private static List<PurchaseItem> lines(Connection c,UUID id)throws SQLException{List<PurchaseItem> out=new ArrayList<>();try(PreparedStatement s=c.prepareStatement("select product_id,lot,expires_on,quantity,unit_cost from purchase_request_line where request_id=? order by line_no")){s.setObject(1,id);try(ResultSet r=s.executeQuery()){while(r.next())out.add(new PurchaseItem(r.getLong(1),r.getString(2),r.getDate(3).toLocalDate(),r.getInt(4),r.getBigDecimal(5)));}}return out;}
 public List<Pending> list(Security.User u)throws SQLException{u.admin();List<Pending> out=new ArrayList<>();try(Connection c=db.connection()){Security.verify(c,u,true);try(PreparedStatement s=c.prepareStatement("select request_id,supplier_id from purchase_request where (actor_id=? or "+u.role().equals("ADMIN")+") and acknowledged_at is null order by created_at")){s.setLong(1,u.id());try(ResultSet r=s.executeQuery()){while(r.next()){UUID id=(UUID)r.getObject(1);out.add(new Pending(id,(Long)r.getObject(2),List.copyOf(lines(c,id))));}}}}return out;}
 public long resolve(Security.User user,UUID id)throws SQLException {user.admin();Pending pending;try(Connection c=db.connection()){Security.verify(c,user,true);try(PreparedStatement q=c.prepareStatement("select supplier_id,cancelled from purchase_request where request_id=? and (actor_id=? or "+user.role().equals("ADMIN")+")")){q.setObject(1,id);q.setLong(2,user.id());try(ResultSet r=q.executeQuery()){if(!r.next()||r.getBoolean(2))throw new IllegalArgumentException("Solicitud de compra inexistente o cancelada");pending=new Pending(id,(Long)r.getObject(1),lines(c,id));}}}return operations.purchase(user,pending.supplier(),pending.items(),id);}
 public void cancelOrDiscard(Security.User u,UUID id)throws SQLException {u.admin();try(Connection c=db.connection()){c.setAutoCommit(false);try{Security.verify(c,u,true);try(PreparedStatement l=c.prepareStatement("select pg_advisory_xact_lock(hashtextextended(?,0))")){l.setString(1,"sigf_purchase_pending:"+u.id());l.execute();}try(PreparedStatement l=c.prepareStatement("select pg_advisory_xact_lock(hashtextextended(?,0))")){l.setString(1,id.toString());l.execute();}try(PreparedStatement q=c.prepareStatement("select exists(select 1 from purchase where request_id=?)")){q.setObject(1,id);try(ResultSet r=q.executeQuery()){r.next();if(r.getBoolean(1))throw new IllegalArgumentException("La compra ya se registró; resuélvala en Compras pendientes");}}try(PreparedStatement q=c.prepareStatement("select actor_id from purchase_request where request_id=?")){q.setObject(1,id);try(ResultSet r=q.executeQuery()){if(r.next()&&r.getLong(1)!=u.id())throw new SecurityException("Solicitud ajena");}}try(PreparedStatement q=c.prepareStatement("update purchase_request set acknowledged_at=now(),cancelled=true where request_id=? and (actor_id=? or "+u.role().equals("ADMIN")+") and acknowledged_at is null")){q.setObject(1,id);q.setLong(2,u.id());q.executeUpdate();}c.commit();}catch(Exception e){c.rollback();throw e;}}}
 public void acknowledge(Security.User user,UUID id,boolean cancel)throws SQLException{user.admin();try(Connection c=db.connection()){c.setAutoCommit(false);try{Security.verify(c,user,true);try(PreparedStatement lock=c.prepareStatement("select pg_advisory_xact_lock(hashtextextended(?,0))")){lock.setString(1,id.toString());lock.execute();}boolean committed;try(PreparedStatement q=c.prepareStatement("select exists(select 1 from purchase where request_id=?)")){q.setObject(1,id);try(ResultSet r=q.executeQuery()){r.next();committed=r.getBoolean(1);}}if(cancel&&committed)throw new IllegalArgumentException("La compra ya está registrada; resuelva la solicitud");if(!cancel&&!committed)throw new IllegalArgumentException("La compra aún no está registrada");try(PreparedStatement s=c.prepareStatement("update purchase_request set acknowledged_at=now(),cancelled=? where request_id=? and (actor_id=? or "+user.role().equals("ADMIN")+") and acknowledged_at is null")){s.setBoolean(1,cancel);s.setObject(2,id);s.setLong(3,user.id());if(s.executeUpdate()!=1){try(PreparedStatement q=c.prepareStatement("select cancelled from purchase_request where request_id=? and (actor_id=? or "+user.role().equals("ADMIN")+") and acknowledged_at is not null")){q.setObject(1,id);q.setLong(2,user.id());try(ResultSet r=q.executeQuery()){if(!r.next()||r.getBoolean(1)!=cancel)throw new IllegalArgumentException("Solicitud inexistente o ya cerrada");}}}}org.sigf.repositories.AuditRepository.write(c,user,"PURCHASE_PENDING_RECONCILE",id+" cancel="+cancel);c.commit();}catch(Exception e){c.rollback();throw e;}}}
}
